def run_order(tasks):
    order = []
    visited = set()
    visiting = set()

    def visit(name):
        if name not in tasks:
            raise KeyError(f"Task '{name}' not found in tasks")
        if name in visiting:
            raise ValueError(f"Circular dependency detected involving task '{name}'")
        if name in visited:
            return

        visiting.add(name)
        for dep in tasks[name]:
            visit(dep)
        visiting.remove(name)

        visited.add(name)
        order.append(name)

    for name in tasks:
        if name not in visited:
            visit(name)
    return order
